# area: generics_variance
# hypothesis: A PEP 695 class that stores Callable[[T], None] in a tuple and exposes it through a property setter lets mypy accept Handler[float] where Handler[int] is expected, and the call fails at runtime.
from typing import Callable, reveal_type


class Handler[T]:
    def __init__(self, cbs: tuple[Callable[[T], None], ...]) -> None:
        self._cbs = cbs

    @property
    def cbs(self) -> tuple[Callable[[T], None], ...]:
        return self._cbs

    @cbs.setter
    def cbs(self, value: tuple[Callable[[T], None], ...]) -> None:
        self._cbs = value


def bit_len(v: int) -> None:
    v.bit_length()


def frac(x: float) -> None:
    x.is_integer()


def use(h: Handler[int]) -> None:
    h.cbs = (bit_len,)


def probe(h: Handler[float]) -> bool:
    use(h)  # expect-error
    try:
        h.cbs[0](1.5)
    except AttributeError:
        return True
    return False


hf = Handler[float]((frac,))
reveal_type(hf.cbs)
frac(2.0)
bit_len(3)
assert probe(hf)
